test('precision edit reuses request identity after an unconfirmed response',async()=>{const b=boot();try{await tick();b.w.eval("currentUser={id:'owner'};trainingFocusReady=true;trainingFocusActive={id:'old'};loadTrainingFocus=async()=>{};");const calls=[];b.setRpc(async(name,args)=>{calls.push(args);return calls.length===1?{data:null,error:{message:'Antwort unterbrochen'}}:{data:{id:args.p_request_id},error:null}});await assert.rejects(b.w.reviseTrainingFocus('Wenn FOMO, dann Pause.',{id:'old'}));await b.w.reviseTrainingFocus('Wenn FOMO, dann Pause.',{id:'old'});assert.equal(calls.length,2);assert.equal(calls[0].p_request_id,calls[1].p_request_id);}finally{b.close()}});

test('V742 account workspace shows no settings and Playbook has no duplicate navigation',async()=>{const b=boot();try{await tick();b.w.showView('accounts');assert.equal(b.w.document.getElementById('settingsView').classList.contains('hidden'),true);assert.equal(b.w.document.querySelector('#playbookView>.subnav').hidden,true);assert.equal(b.w.document.getElementById('analysisPlaybookTab').hidden,true);}finally{b.close()}});
test('V742 missing review item opens its exact step and field',async()=>{const b=boot();try{await tick();const t=trade737Fixture(b,true);await b.w.openTradeDetails(t);b.w.showView('journal');const d=b.w.document,button=[...d.querySelectorAll('.missing-link')].find(x=>x.textContent.includes('Ausführungsqualität'));assert.ok(button);button.click();assert.equal(d.getElementById('tradeDetails').dataset.activePane,'review');assert.equal(d.querySelector('.review-editor').dataset.reviewStep,'2');assert.equal(d.activeElement,d.querySelector('.review-grade'),JSON.stringify((()=>{let n=d.querySelector('.review-grade'),out=[];while(n){out.push([n.tagName,n.id,n.className,n.hidden,n.disabled,n.open]);n=n.parentElement;}return out;})()));assert.equal(d.querySelector('[data-review-step="1"]').hidden,true);}finally{b.close()}});
test('V742 review navigation preserves unsaved learning notes and exposes final save only last',async()=>{const b=boot();try{await tick();await b.w.openTradeDetails(trade737Fixture(b,true));const form=b.w.document.querySelector('.review-editor');assert.equal(form.querySelector('.review-save').hidden,true);b.w.showReviewStep742(form,3,false);form.querySelector('.review-note').value='Mein konkreter Lernpunkt';assert.equal(form.querySelector('.review-save').hidden,false);b.w.showReviewStep742(form,1,false);b.w.showReviewStep742(form,3,false);assert.equal(form.querySelector('.review-note').value,'Mein konkreter Lernpunkt');}finally{b.close()}});
test('V742 overview omits inferred holding duration and uses compact review status',async()=>{const b=boot();try{await tick();const host=b.w.document.createElement('div');b.w.addTradeOverview(host,trade737Fixture(b,true),[],new Map());assert.doesNotMatch(host.textContent,/Haltedauer|min/);assert.match(host.textContent,/Initialrisiko/);await b.w.openTradeDetails(trade737Fixture(b,true));assert.doesNotMatch(b.w.document.getElementById('tradeDetails').textContent,/Haltedauer/);}finally{b.close()}});
test('V742 native paste accepts files-only payload and rejects arbitrary HTML',async()=>{const b=boot();try{await tick();const d=b.w.document,zone=d.getElementById('htfDropzone'),field=zone.querySelector('.image-paste-field'),file=new b.w.File(['image'],'screenshot.png',{type:'image/png'});const e=new b.w.Event('paste',{bubbles:true,cancelable:true});Object.defineProperty(e,'clipboardData',{value:{files:[file],items:[],getData:()=>''}});field.dispatchEvent(e);assert.equal(e.defaultPrevented,true);assert.equal(b.w.chosenImages(zone).length,1);assert.ok(zone.querySelector('.pending-image-preview img'));const bad=new b.w.Event('paste',{bubbles:true,cancelable:true});Object.defineProperty(bad,'clipboardData',{value:{files:[],items:[],getData:()=>'<img src="https://evil.invalid/a"><script>bad()</script>'}});field.dispatchEvent(bad);assert.equal(field.querySelector('img'),null);assert.equal(b.w.chosenImages(zone).length,1);}finally{b.close()}});
test('V742 native clipboard items and files do not duplicate a single screenshot',async()=>{const b=boot();try{await tick();const file=new b.w.File(['image'],'screenshot.png',{type:'image/png'});assert.equal(b.w.clipboardImageFiles({files:[file],items:[{kind:'file',getAsFile:()=>file}]}).length,1);}finally{b.close()}});
